code_sketch:
cl, err := kgo.NewClient(kgo.SeedBrokers(brokers...),
    kgo.RequiredAcks(kgo.AllISRAcks()),   // idempotent writes are the default
    kgo.RecordRetries(20))
if err != nil { return err }
defer cl.Close()
res := cl.ProduceSync(ctx, &kgo.Record{Topic: "orders", Key: []byte(id), Value: body})
if err := res.FirstErr(); err != nil {
    writeSpool(id, body)                  // the broker did not persist it
    return err
}

